// ---------------------------------------------------------------------------
// Build request
//
// Spring is the only source of truth. This node never invents a service, never
// reaches a database, and never decides what is safe. It validates the shape of
// what arrived and turns it into one prompt string.
// ---------------------------------------------------------------------------
const req = $input.first().json.body ?? {};

const errors = [];
if (!req.formId) errors.push('formId is required');
if (!req.intent) errors.push('intent is required');
if (!Array.isArray(req.allowedServices) || req.allowedServices.length === 0) {
  errors.push('allowedServices must be a non-empty array');
}
if (errors.length > 0) {
  return [{ json: { ok: false, errors, formId: req.formId ?? null } }];
}

// The catalogue is the ONLY thing the model may choose from. Spring has already
// removed every service the spa-authored ServiceProtocol table marks
// CONTRAINDICATED for this client. The model is not asked to judge safety --
// it cannot, and being asked would make this a medical device.
const catalogue = req.allowedServices.map(function (s, i) {
  return (i + 1) + '. id=' + s.serviceId +
         ' | ' + s.name +
         ' | ' + s.durationMinutes + ' min' +
         ' | PHP ' + s.price +
         (s.rationale ? ' | note: ' + s.rationale : '');
}).join('\n');

const painSummary = (req.painPoints ?? []).map(function (p) {
  const side = (p.side && p.side !== 'CENTRE') ? ' (' + String(p.side).toLowerCase() + ')' : '';
  return '- ' + p.anatomicalRegion + side + ', pain ' + p.painScoreBefore + '/10';
}).join('\n') || '- none marked';

const flags = req.flags && Object.keys(req.flags).length
  ? Object.keys(req.flags).filter(function (k) { return req.flags[k]; }).join(', ') || 'none reported'
  : 'none reported';

const prompt = [
  'You are the booking assistant for HilotSpa, a traditional Filipino hilot and',
  'wellness spa in Bulan, Sorsogon.',
  '',
  'YOUR ONLY JOB is to rank the services listed below for this client and explain',
  'each choice in one plain sentence a non-medical person understands.',
  '',
  'HARD RULES:',
  '- Choose ONLY from the numbered list. Never name a service that is not on it.',
  '- Copy the id EXACTLY as written. Do not shorten, reformat, or invent ids.',
  '- Do NOT diagnose. Do NOT name a condition the client did not name.',
  '- Do NOT give medical advice, treatment plans, or prognosis.',
  '- Do NOT promise a cure or an outcome.',
  '- If the client should see a doctor, say only: "please consider seeing a',
  '  physician" -- nothing more specific.',
  '- Reply with STRICT JSON only. No prose, no markdown fences.',
  '',
  'CLIENT ASSESSMENT',
  'Reason for visit: ' + (req.intent === 'PAIN' ? 'pain or discomfort' : 'relaxation / leisure'),
  'Chief complaint: ' + (req.chiefComplaint ?? 'not stated'),
  'How long: ' + (req.chiefComplaintDuration ?? 'not stated'),
  'Marked areas:',
  painSummary,
  'Safety flags reported: ' + flags,
  'Preferred pressure: ' + (req.pressurePreference ?? 'not stated'),
  '',
  'AVAILABLE SERVICES (the complete and only permitted set):',
  catalogue,
  '',
  'Return exactly this JSON shape, at most 3 recommendations, best first:',
  '{"recommendations":[{"serviceId":"<id copied from the list>","reason":"<one sentence>"}]}'
].join('\n');

return [{
  json: {
    ok: true,
    formId: req.formId,
    intent: req.intent,
    chiefComplaint: req.chiefComplaint ?? null,
    allowedServices: req.allowedServices,
    prompt: prompt
  }
}];

// ---------------------------------------------------------------------------
// Validate and rank
//
// This is the safety boundary, and it is the reason the assistant can be
// defended in the paper. Whatever the model said, only a serviceId that Spring
// itself sent in allowedServices can survive this node. A hallucinated id, a
// contraindicated service, a reworded name -- all are dropped, not corrected.
//
// It reads allowedServices from the "Build request" node rather than from its
// own input, so it behaves identically whether the Gemini node is enabled or
// disabled.
// ---------------------------------------------------------------------------
const built = $('Build request').first().json;
const now = new Date().toISOString();

if (built.ok === false) {
  return [{ json: {
    formId: built.formId,
    status: 'ERROR',
    errors: built.errors,
    recommendations: [],
    modelUsed: 'none',
    generatedAt: now
  } }];
}

const allowed = new Map(built.allowedServices.map(function (s) {
  return [String(s.serviceId), s];
}));

// --- read the model answer, if there is one -------------------------------
// Three different things can arrive here and they must not be confused:
//   1. the Vertex node is DEACTIVATED  -> n8n passes Build request through, so
//      the input still carries .prompt
//   2. the Vertex node RAN AND FAILED  -> Google's error body arrives, because
//      the node is set neverError so a 401 does not stop the workflow
//   3. the Vertex node SUCCEEDED       -> .candidates is present
// Collapsing 1 and 2 into "stub" hides a broken credential behind a healthy
// looking FALLBACK, which is exactly the bug that eats an afternoon.
let picks = [];
let modelUsed = 'stub';
let parseError = null;

const raw = $input.first().json;

const wasSkipped = raw && Object.prototype.hasOwnProperty.call(raw, 'prompt');
const googleError = raw && raw.error ? raw.error : null;

if (googleError) {
  modelUsed = 'error';
  parseError = 'Vertex rejected the call: '
             + (googleError.code ? googleError.code + ' ' : '')
             + (googleError.status ? googleError.status + ' - ' : '')
             + (googleError.message || 'no message');
} else if (wasSkipped) {
  modelUsed = 'stub';
  parseError = null;
} else {
  const text = raw && raw.candidates && raw.candidates[0] &&
               raw.candidates[0].content && raw.candidates[0].content.parts &&
               raw.candidates[0].content.parts[0]
               ? raw.candidates[0].content.parts[0].text
               : null;

  if (text) {
    modelUsed = raw.modelVersion || 'vertex-gemini';
    const finish = raw.candidates[0].finishReason || null;
    const usage  = raw.usageMetadata || {};

    // Be liberal about what the model wraps its JSON in, but never about what
    // comes out the other side - the guard below is unchanged.
    let cleaned = String(text).trim();
    const fenced = cleaned.match(/```(?:json)?\s*([\s\S]*?)```/i);
    if (fenced) { cleaned = fenced[1].trim(); }
    const open = cleaned.indexOf('{');
    const close = cleaned.lastIndexOf('}');
    if (open !== -1 && close > open) { cleaned = cleaned.slice(open, close + 1); }

    try {
      const parsed = JSON.parse(cleaned);
      if (Array.isArray(parsed.recommendations)) {
        picks = parsed.recommendations;
      } else {
        parseError = 'JSON parsed but had no recommendations array. Keys: '
                   + Object.keys(parsed).join(', ');
      }
    } catch (e) {
      // Say WHAT came back. "not valid JSON" with the evidence discarded is
      // how the last hour was spent guessing.
      parseError = 'Could not parse the model reply.'
        + ' finishReason=' + finish
        + ' thoughtTokens=' + (usage.thoughtsTokenCount ?? '?')
        + ' answerTokens=' + (usage.candidatesTokenCount ?? '?')
        + ' | raw starts: ' + String(text).slice(0, 200).replace(/\s+/g, ' ');
    }
  } else {
    modelUsed = 'error';
    parseError = 'Vertex returned no candidates and no error object';
  }
}

// --- the guard ------------------------------------------------------------
const seen = new Set();
const kept = [];
let rejected = 0;

for (const p of picks) {
  const id = p && p.serviceId != null ? String(p.serviceId) : null;
  if (!id || !allowed.has(id) || seen.has(id)) { rejected++; continue; }
  seen.add(id);
  kept.push({
    serviceId: id,
    rank: kept.length + 1,
    reason: String(p.reason ?? '').slice(0, 300)
  });
  if (kept.length === 3) break;
}

// --- fallback: the protocol table answers when the model cannot ------------
let status = 'OK';
let recommendations = kept;

if (recommendations.length === 0) {
  status = 'FALLBACK';
  const indicated = built.allowedServices.filter(function (s) { return s.rule === 'INDICATED'; });
  const rest     = built.allowedServices.filter(function (s) { return s.rule !== 'INDICATED'; });
  recommendations = indicated.concat(rest).slice(0, 3).map(function (s, i) {
    return {
      serviceId: String(s.serviceId),
      rank: i + 1,
      reason: s.rationale || 'Listed for this assessment in the spa’s own service protocol.'
    };
  });
}

return [{ json: {
  formId: built.formId,
  status: status,
  recommendations: recommendations,
  modelUsed: modelUsed,
  rejectedCount: rejected,
  parseError: parseError,
  generatedAt: now
} }];
